CI_WORKFLOW = """name: runtime-supervisor

on: [pull_request]

jobs:
  check-supervision:
    runs-on: ubuntu-latest
    steps:
      - uses: actions/checkout@v4
      - uses: astral-sh/setup-uv@v4
      - name: Rescan repo
        run: |
          uv run --with supervisor-discover supervisor-discover scan --dry-run > /tmp/current-findings.json
      - name: Diff against committed findings
        run: |
          diff -u runtime-supervisor/findings.json /tmp/current-findings.json || {
            echo "::error::Unsupervised call-sites changed. Re-run `supervisor-discover scan` locally and commit the updated runtime-supervisor/ directory."
            exit 1
          }
"""


# -----------------------------------------------------------------------------
# Governance pack scaffolds — used by governance.py
#
# Each scaffold is rendered with `.format(...)`. Interpolated fields are listed
# at the top of every scaffold. Every dynamic value comes from RepoSummary or
# findings — no hardcoded numbers, providers, or action types may leak into the
# fixed text. When a list is empty, the renderer substitutes a `_None ..._`
